import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        vm.deal(address(this), 1 ether);
        c = new C{value: 1 ether}();
    }
    function testFuzz_property(address caller, bytes32 hash) public {
        vm.assume(caller != address(0) && caller != address(c) && caller != address(this));
        vm.deal(caller, 2 ether);
        vm.prank(caller);
        bool success;
        try c.lockInGuess{value: 1 ether}(hash) {
            success = true;
        } catch {
            success = false;
        }
        // After a call with exactly 1 ether, the reference must succeed (success == true),
        // while the buggy version requires 2 ether and will revert (success == false).
        assertTrue(success);
    }
}

