pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, bytes32 guess) public {
        vm.assume(sender != address(0));
        vm.assume(!_isContract(sender));
        vm.deal(sender, 1 ether);
        uint256 balanceBefore = address(c).balance;
        vm.prank(sender);
        try c.lockInGuess{value: 1 ether}(guess) {
            uint256 distinctSenders = 0;
            // We cannot iterate over mappings, but we can check the balance invariant:
            // After a successful lockInGuess from a new sender, the balance must increase by exactly 1 ether
            // compared to before the call. If the sender was already used, the call reverts and balanceBefore==balanceAfter.
            uint256 balanceAfter = address(c).balance;
            // The rule: either the call reverted (balance unchanged) or the balance increased by exactly 1 ether.
            // However the bug allows locking without payment; then balanceAfter would be strictly less than balanceBefore+1ether
            // when 1 ether was sent. To capture this universally, we assert:
            // After any call (with 1 ether sent), the contract balance is either unchanged (revert) or exactly balanceBefore+1ether.
            assertTrue(balanceAfter == balanceBefore || balanceAfter == balanceBefore + 1 ether);
        } catch {
            // Call reverted, balance must be unchanged
            assertTrue(address(c).balance == balanceBefore);
        }
    }
    function _isContract(address a) internal view returns (bool) {
        uint256 size;
        assembly { size := extcodesize(a) }
        return size > 0;
    }
}

