pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user, bytes32 guess1, bytes32 guess2) public {
        vm.assume(user != address(0));

        // Fund the contract so it can pay out
        vm.deal(address(c), 2 ether);

        // First lock: send 1 ether
        vm.deal(user, 2 ether);
        vm.prank(user);
        c.lockInGuess{value: 1 ether}(guess1);

        // Second lock: try to overwrite with another 1 ether
        vm.prank(user);
        c.lockInGuess{value: 1 ether}(guess2);

        // Now settle: advance blocks to be past the stored block
        vm.roll(block.number + 10);
        vm.prank(user);
        c.settle();

        // After settle, the user's block must be zero (cleared).
        // Under the bug, the first lock's block is overwritten by the second lock,
        // but settle clears the block after using it, so the final block is still zero.
        // However, the bug allows the first lock's guess to trigger a payout
        // when settle uses the block of the second lock, and the blockhash matches guess1.
        // We assert that the user's balance cannot increase by more than 1 ether
        // if the second lock overwrote the first. Actually, property: if a user
        // can lockInGuess twice, settle should NOT transfer 2 ether total
        // (the reference prevents the second lock, so only 1 ether can be extracted).
        // The fuzzer will find guess1 that matches the blockhash of the second lock's block,
        // leading to a double payout in the buggy version.
        assertTrue(user.balance <= 2 ether + 1 ether);
    }
}

