pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockDelta) public {
        vm.assume(blockDelta > 0 && blockDelta <= 256);
        vm.assume(block.number + blockDelta > block.number);

        address actor = address(uint160(uint256(keccak256(abi.encodePacked(blockDelta, block.number)))));
        bytes32 guess = bytes32(uint256(1));

        vm.deal(actor, 2 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);

        vm.roll(block.number + blockDelta);

        vm.prank(actor);
        try c.settle() { } catch { }

        uint256 recordedBlock = c.guesses(actor).block;
        bool canSettle = (recordedBlock == 0) || (recordedBlock != 0 && block.number > recordedBlock);
        assertTrue(recordedBlock == block.number - blockDelta + 1 || !canSettle);
    }
}

