pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash, uint256 settleBlockOffset) public {
        // Bind to keep within reasonable block window (beyond 256 blocks blockhash returns 0)
        settleBlockOffset = bound(settleBlockOffset, 1, 255);
        address actor = address(this);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash);
        uint256 guessBlock = block.number + settleBlockOffset;
