        settleDelay = bound(settleDelay, 1, 256);
        // Contract must start with at least 2 ether to cover the payout
        initialBalance = bound(initialBalance, 2 ether, type(uint128).max);

        // Fund contract so it can pay out on a correct guess
        vm.deal(address(c), initialBalance);

