        // Advance past the guessing block so blockhash is potentially nonzero
        vm.roll(block.number + 1);

        uint256 balanceBefore = address(c).balance;

        vm.prank(user);
        try c.settle() {} catch {}

        uint256 balanceAfter = address(c).balance;

        // If the guess was correct (blockhash matches guessHash), the contract should have paid out exactly 2 ether.
        // The invariant: after settle, if balance decreased, it must have decreased by exactly 2 ether.
        // The buggy version only pays 1 ether, so the balance change violates this.
        if (balanceBefore != balanceAfter) {
