contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guessHash) public {
        // Adversarial counterparty: an EOA cannot lock a guess because lockInGuess requires 1 ether.
        // The fuzzer provides the guess hash; we must be able to lock and settle.
        address guesser = makeAddr("guesser");
        vm.deal(guesser, 1 ether);
        vm.prank(guesser);
        c.lockInGuess{value: 1 ether}(guessHash);

