        uint256 balanceBefore = address(c).balance;
        vm.prank(guesser);
        c.settle();
        uint256 balanceAfter = address(c).balance;

        // The general rule: after settle, the contract's balance is balanceBefore minus 2 ether
        // if and only if the chain condition (blockhash non-zero and guess matches) holds.
        // But the reference always pays 2 ether on success; buggy pays 1.
        // We assert that if the transfer happened (contract balance decreased),
        // the decrease is exactly 2 ether. This holds for reference, fails for mutant.
        if (balanceAfter < balanceBefore) {
            assertEq(balanceBefore - balanceAfter, 2 ether, "Contract must pay exactly 2 ether");
        }
