pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        vm.deal(address(this), 2 ether);
        c = new C{value: 1 ether}();
    }

    function testFuzz_property(bytes32 hash, uint256 blockOffset) public {
        // Keep blockOffset reasonable: future block number must stay within 256 of lock-in block
        blockOffset = bound(blockOffset, 2, 255);
        address actor = address(0x1234);
        vm.deal(actor, 2 ether);

        // Step 1: lock in a guess with a hash that will NOT match the future blockhash
        vm.startPrank(actor);
        c.lockInGuess{value: 1 ether}(hash);
        vm.stopPrank();

        // Advance to a future block where blockhash is non-zero (<=256 blocks after lock-in)
        uint256 targetBlock = block.number + blockOffset;
        vm.roll(targetBlock);

        // Ensure blockhash is non-zero by setting a predictable one if needed
        // We can't control blockhash, but we can ensure we're within 256 blocks of lock-in
        // The lock-in block was block.number + 1 at time of lockInGuess, so target - (lock-1) <=256
        vm.assume(targetBlock > block.number - 1);

        // Step 2: settle and record whether payment was received
        uint256 balanceBefore = actor.balance;
        vm.prank(actor);
        c.settle();
        uint256 balanceAfter = actor.balance;

        // If payment occurred (balance increased by 2 ether), it implies guess matched the blockhash.
        // The reference version only pays when guess == blockhash; the buggy version pays for any non-zero blockhash.
        bool paymentReceived = (balanceAfter > balanceBefore);
        bool guessMatchesBlockhash = (blockhash(block.number - blockOffset + 1) == hash);

        // The invariant: payment => guess matches blockhash
        assertTrue(!paymentReceived || guessMatchesBlockhash);
    }
}

